import * as React from "react";
import { renderToString } from "react-dom/server";

import { ApolloClient, InMemoryCache, gql } from "@apollo/client";
import { ApolloProvider, useQuery } from "@apollo/client/react";
import { prerenderStatic, resetApolloContext } from "@apollo/client/react/ssr";

const QUERY = gql`
  {
    hello
  }
`;

function makeClient() {
  return new ApolloClient({
    cache: new InMemoryCache(),
    link: {
      request: () => {
        throw new Error("network should never be hit");
      },
    } as any,
  });
}

const renders: Array<{ loading: boolean; networkStatus: number; data: any }> =
  [];

function Component() {
  const { data, loading, networkStatus } = useQuery(QUERY, {
    ssr: false,
    skip: true,
  });
  renders.push({ loading, networkStatus, data });
  return <div>skipped:{String(loading)}</div>;
}

test("ssr:false + skip:true hydrates with no mismatch and consistent ready state", async () => {
  // ---- server ----
  const ssrClient = makeClient();
  const { result: html } = await prerenderStatic({
    tree: (
      <ApolloProvider client={ssrClient}>
        <Component />
      </ApolloProvider>
    ),
    renderFunction: renderToString,
  });

  // cache must remain empty
  expect(ssrClient.extract()).toEqual({});

  // ---- client hydration ----
  resetApolloContext();
  renders.length = 0;

  const jsdom = new JSDOM(`<div id="root">${html}</div>`);
  const container = jsdom.window.document.getElementById("root")!;

  // point React DOM at this jsdom
  (global as any).window = jsdom.window;
  (global as any).document = jsdom.window.document;

  const errors: any[] = [];
  const clientClient = makeClient();
  const reactClient = await import("react-dom/client");
  const root = reactClient.hydrateRoot(
    container,
    <ApolloProvider client={clientClient}>
      <Component />
    </ApolloProvider>,
    {
      onRecoverableError: (e: any) => errors.push(e),
    }
  );

  await new Promise((r) => setTimeout(r, 300));

  expect(errors).toEqual([]);
  // every render consistent
  for (const r of renders) {
    expect(r.loading).toBe(false);
    expect(r.networkStatus).toBe(7);
    expect(r.data).toBeUndefined();
  }
  root.unmount();
});
