import { prerenderStatic, resetApolloContext } from "@apollo/client/react/ssr";

const QUERY = gql`
  {
    hello
  }
`;

function makeClient() {
  return new ApolloClient({
    cache: new InMemoryCache(),
    link: {
      request: () => {
        throw new Error("network should never be hit");
      },
    } as any,
  });
}

const renders: Array<{ loading: boolean; networkStatus: number; data: any }> =
  [];

function Component() {
