erHookToSnapshotStream,\n} from \"@testing-library/react-render-stream\";\nimport { from } from \"rxjs\";\n\nimport {\n  ApolloClient,\n  ApolloLink,\n  CombinedGraphQLErrors,\n  gql,\n  InMemoryCache,\n  NetworkStatus,\n} from \"@apollo/client\";\nimport { GraphQL17Alpha9Handler } from \"@apollo/client/incremental\";\nimport { useQuery } from \"@apollo/client/react\";\nimport {\n  asyncIterableSubject,\n  createClientWrapper,\n  executeSchemaGraphQL17Alpha9,\n  friendListSchemaGraphQL17Alpha9,\n  markAsStreaming,\n  spyOnConsole,\n} from \"@apollo/client/testing/internal\";\n\nfunction createLink(rootValue?: unknown) {\n  return new ApolloLink((operation) => {\n    return from(\n      executeSchemaGraphQL17Alpha9(\n        friendListSchemaGraphQL17Alpha9,\n        operation.query,\n        rootValue\n      )\n    );\n  });\n}\n\nconst friends = [\n  { name: \"Luke\", id: 1 },\n  { name: \"Han\", id: 2 },\n  { name: \"Leia\", id: 3 },\n];\n\ntype Friend = (typeof friends)[number];\n\ntest(\"should handle streamed queries\", async () => {\n  const { stream, subject } = asyncIterableSubject<Friend>();\n\n  const query = gql`\n    query {\n      friendList @stream(initialCount: 1) {\n        id\n        name\n      }\n    }\n  `;\n\n  const client = new ApolloClient({\n    link: createLink({ friendList: () => stream }),\n    cache: new InMemoryCache(),\n    incrementalHandler: new GraphQL17Alpha9Handler(),\n  });\n\n  using _disabledAct = disableActEnvironment();\n  const { takeSnapshot } = await renderHookToSnapshotStream(\n    () => useQuery(query),\n    { wrapper: createClientWrapper(client) }\n  );\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: undefined,\n    dataState: \"empty\",\n    loading: true,\n    networkStatus: NetworkStatus.loading,\n    previousData: undefined,\n    variables: {},\n  });\n\n  subject.next(friends[0]);\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: markAsStreaming({\n      friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }],\n    }),\n    dataState: \"streaming\",\n    loading: true,\n    networkStatus: NetworkStatus.streaming,\n    previousData: undefined,\n    variables: {},\n  });\n\n  subject.next(friends[1]);\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: markAsStreaming({\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Han\" },\n      ],\n    }),\n    dataState: \"streaming\",\n    loading: true,\n    networkStatus: NetworkStatus.streaming,\n    previousData: {\n      friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }],\n    },\n    variables: {},\n  });\n\n  subject.next(friends[2]);\n  subject.complete();\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: markAsStreaming({\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Han\" },\n        { __typename: \"Friend\", id: \"3\", name: \"Leia\" },\n      ],\n    }),\n    dataState: \"streaming\",\n    loading: true,\n    networkStatus: NetworkStatus.streaming,\n    previousData: {\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Han\" },\n      ],\n    },\n    variables: {},\n  });\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: {\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Han\" },\n        { __typename: \"Friend\", id: \"3\", name: \"Leia\" },\n      ],\n    },\n    dataState: \"complete\",\n    loading: false,\n    networkStatus: NetworkStatus.ready,\n    previousData: {\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Han\" },\n      ],\n    },\n    variables: {},\n  });\n\n  await expect(takeSnapshot).not.toRerender();\n});\n\ntest(\"should handle streamed queries with fetch policy no-cache\", async () => {\n  const { subject, stream } = asyncIterableSubject<Friend>();\n  const query = gql`\n    query {\n      friendList @stream(initialCount: 1) {\n        id\n        name\n      }\n    }\n  `;\n\n  const client = new ApolloClient({\n    link: createLink({ friendList: () => stream }),\n    cache: new InMemoryCache(),\n    incrementalHandler: new GraphQL17Alpha9Handler(),\n  });\n\n  using _disabledAct = disableActEnvironment();\n  const { takeSnapshot } = await renderHookToSnapshotStream(\n    () => useQuery(query, { fetchPolicy: \"no-cache\" }),\n    { wrapper: createClientWrapper(client) }\n  );\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: undefined,\n    dataState: \"empty\",\n    loading: true,\n    networkStatus: NetworkStatus.loading,\n    previousData: undefined,\n    variables: {},\n  });\n\n  subject.next(friends[0]);\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: markAsStreaming({\n      friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }],\n    }),\n    dataState: \"streaming\",\n    loading: true,\n    networkStatus: NetworkStatus.streaming,\n    previousData: undefined,\n    variables: {},\n  });\n\n  subject.next(friends[1]);\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: markAsStreaming({\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Han\" },\n      ],\n    }),\n    dataState: \"streaming\",\n    loading: true,\n    networkStatus: NetworkStatus.streaming,\n    previousData: {\n      friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }],\n    },\n    variables: {},\n  });\n\n  subject.next(friends[2]);\n  subject.complete();\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: markAsStreaming({\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Han\" },\n        { __typename: \"Friend\", id: \"3\", name: \"Leia\" },\n      ],\n    }),\n    dataState: \"streaming\",\n    loading: true,\n    networkStatus: NetworkStatus.streaming,\n    previousData: {\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Han\" },\n      ],\n    },\n    variables: {},\n  });\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: {\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Han\" },\n        { __typename: \"Friend\", id: \"3\", name: \"Leia\" },\n      ],\n    },\n    dataState: \"complete\",\n    loading: false,\n    networkStatus: NetworkStatus.ready,\n    previousData: {\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Han\" },\n      ],\n    },\n    variables: {},\n  });\n\n  await expect(takeSnapshot).not.toRerender();\n});\n\ntest(\"should handle streamed queries with errors returned on the incremental batched result\", async () => {\n  const { stream, subject } = asyncIterableSubject<Friend | Error>();\n  const query = gql`\n    query {\n      friendList @stream(initialCount: 1) {\n        id\n        name\n      }\n    }\n  `;\n\n  const client = new ApolloClient({\n    link: createLink({ friendList: () => stream }),\n    cache: new InMemoryCache(),\n    incrementalHandler: new GraphQL17Alpha9Handler(),\n  });\n\n  using _disabledAct = disableActEnvironment();\n  const { takeSnapshot } = await renderHookToSnapshotStream(\n    () => useQuery(query),\n    { wrapper: createClientWrapper(client) }\n  );\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: undefined,\n    dataState: \"empty\",\n    loading: true,\n    networkStatus: NetworkStatus.loading,\n    previousData: undefined,\n    variables: {},\n  });\n\n  subject.next(friends[0]);\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: markAsStreaming({\n      friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }],\n    }),\n    dataState: \"streaming\",\n    loading: true,\n    networkStatus: NetworkStatus.streaming,\n    previousData: undefined,\n    variables: {},\n  });\n\n  subject.next(new Error(\"Could not load friend\"));\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: {\n      friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }],\n    },\n    dataState: \"complete\",\n    error: new CombinedGraphQLErrors({\n      data: {\n        friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }, null],\n      },\n      errors: [\n        {\n          message: \"Could not load friend\",\n          path: [\"friendList\", 1],\n        },\n      ],\n    }),\n    loading: false,\n    networkStatus: NetworkStatus.error,\n    previousData: undefined,\n    variables: {},\n  });\n\n  // Emit these to show that errorPolicy of none cuts off future updates\n  subject.next(friends[2]);\n  subject.complete();\n\n  await expect(takeSnapshot).not.toRerender();\n});\n\ntest('should handle streamed queries with errors returned on the incremental batched result and errorPolicy \"all\"', async () => {\n  const { stream, subject } = asyncIterableSubject<Friend | Error>();\n  const query = gql`\n    query {\n      friendList @stream(initialCount: 1) {\n        id\n        name\n      }\n    }\n  `;\n\n  const client = new ApolloClient({\n    link: createLink({ friendList: () => stream }),\n    cache: new InMemoryCache(),\n    incrementalHandler: new GraphQL17Alpha9Handler(),\n  });\n\n  using _disabledAct = disableActEnvironment();\n  const { takeSnapshot } = await renderHookToSnapshotStream(\n    () => useQuery(query, { errorPolicy: \"all\" }),\n    { wrapper: createClientWrapper(client) }\n  );\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: undefined,\n    dataState: \"empty\",\n    loading: true,\n    networkStatus: NetworkStatus.loading,\n    previousData: undefined,\n    variables: {},\n  });\n\n  subject.next(friends[0]);\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: markAsStreaming({\n      friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }],\n    }),\n    dataState: \"streaming\",\n    loading: true,\n    networkStatus: NetworkStatus.streaming,\n    previousData: undefined,\n    variables: {},\n  });\n\n  subject.next(new Error(\"Could not load friend\"));\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: markAsStreaming({\n      friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }, null],\n    }),\n    dataState: \"streaming\",\n    error: new CombinedGraphQLErrors({\n      data: {\n        friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }, null],\n      },\n      errors: [\n        {\n          message: \"Could not load friend\",\n          path: [\"friendList\", 1],\n        },\n      ],\n    }),\n    loading: true,\n    networkStatus: NetworkStatus.streaming,\n    previousData: {\n      friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }],\n    },\n    variables: {},\n  });\n\n  subject.next(friends[2]);\n  subject.complete();\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: markAsStreaming({\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n        null,\n        { __typename: \"Friend\", id: \"3\", name: \"Leia\" },\n      ],\n    }),\n    dataState: \"streaming\",\n    error: new CombinedGraphQLErrors({\n      data: {\n        friendList: [\n          { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n          null,\n          { __typename: \"Friend\", id: \"3\", name: \"Leia\" },\n        ],\n      },\n      errors: [\n        {\n          message: \"Could not load friend\",\n          path: [\"friendList\", 1],\n        },\n      ],\n    }),\n    loading: true,\n    networkStatus: NetworkStatus.streaming,\n    previousData: {\n      friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }, null],\n    },\n    variables: {},\n  });\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: {\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n        null,\n        { __typename: \"Friend\", id: \"3\", name: \"Leia\" },\n      ],\n    },\n    dataState: \"complete\",\n    error: new CombinedGraphQLErrors({\n      data: {\n        friendList: [\n          { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n          null,\n          { __typename: \"Friend\", id: \"3\", name: \"Leia\" },\n        ],\n      },\n      errors: [\n        {\n          message: \"Could not load friend\",\n          path: [\"friendList\", 1],\n        },\n      ],\n    }),\n    loading: false,\n    networkStatus: NetworkStatus.error,\n    previousData: {\n      friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }, null],\n    },\n    variables: {},\n  });\n\n  await expect(takeSnapshot).not.toRerender();\n});\n\ntest('returns eventually consistent data from streamed queries with data in the cache while using a \"cache-and-network\" fetch policy', async () => {\n  const { subject, stream } = asyncIterableSubject<Friend>();\n  const query = gql`\n    query {\n      friendList @stream(initialCount: 1) {\n        id\n        name\n      }\n    }\n  `;\n\n  const client = new ApolloClient({\n    cache: new InMemoryCache({\n      typePolicies: {\n        Query: {\n          fields: {\n            friendList: {\n              merge: (_, incoming) => incoming,\n            },\n          },\n        },\n      },\n    }),\n    link: createLink({ friendList: () => stream }),\n    incrementalHandler: new GraphQL17Alpha9Handler(),\n  });\n\n  client.writeQuery({\n    query,\n    data: {\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Cached Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Cached Han\" },\n        { __typename: \"Friend\", id: \"3\", name: \"Cached Leia\" },\n      ],\n    },\n  });\n\n  using _disabledAct = disableActEnvironment();\n  const { takeSnapshot } = await renderHookToSnapshotStream(\n    () => useQuery(query, { fetchPolicy: \"cache-and-network\" }),\n    { wrapper: createClientWrapper(client) }\n  );\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: {\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Cached Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Cached Han\" },\n        { __typename: \"Friend\", id: \"3\", name: \"Cached Leia\" },\n      ],\n    },\n    dataState: \"complete\",\n    loading: true,\n    networkStatus: NetworkStatus.loading,\n    previousData: undefined,\n    variables: {},\n  });\n\n  subject.next(friends[0]);\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: markAsStreaming({\n      friendList: [{ __typename: \"Friend\", id: \"1\", name: \"Luke\" }],\n    }),\n    dataState: \"streaming\",\n    loading: true,\n    networkStatus: NetworkStatus.streaming,\n    previousData: {\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Cached Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Cached Han\" },\n        { __typename: \"Friend\", id: \"3\", name: \"Cached Leia\" },\n      ],\n    },\n    variables: {},\n  });\n\n  subject.next(friends[1]);\n\n  await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n    data: markAsStreaming({\n      friendList: [\n        { __typename: \"Friend\", id: \"1\", name: \"Luke\" },\n        { __typename: \"Friend\", id: \"2\", name: \"Han\" },\