\n} from \"@apollo/client/testing/internal\";\nimport { MockedProvider } from \"@apollo/client/testing/react\";\nimport type { DeepPartial } from \"@apollo/client/utilities\";\nimport { InvariantError } from \"@apollo/client/utilities/invariant\";\n\ndescribe(\"useLazyQuery Hook\", () => {\n  const helloQuery: TypedDocumentNode<{\n    hello: string;\n  }> = gql`\n    query {\n      hello\n    }\n  `;\n\n  it(\"should hold query execution until manually triggered\", async () => {\n    const mocks = [\n      {\n        request: { query: helloQuery },\n        result: { data: { hello: \"world\" } },\n        delay: 50,\n      },\n    ];\n\n    using _disabledAct = disableActEnvironment();\n    const { takeSnapshot, getCurrentSnapshot } =\n      await renderHookToSnapshotStream(() => useLazyQuery(helloQuery), {\n        wrapper: ({ children }) => (\n          <MockedProvider mocks={mocks}>{children}</MockedProvider>\n        ),\n      });\n\n    {\n      const [, result] = await takeSnapshot();\n\n      expect(result).toStrictEqualTyped({\n        data: undefined,\n        dataState: \"empty\",\n        called: false,\n        loading: false,\n        networkStatus: NetworkStatus.ready,\n        previousData: undefined,\n        variables: {},\n      });\n    }\n\n    const [execute] = getCurrentSnapshot();\n    const result = await execute();\n\n    expect(result).toStrictEqualTyped({\n      data: { hello: \"world\" },\n    });\n\n    {\n      const [, result] = await takeSnapshot();\n\n      expect(result).toStrictEqualTyped({\n        data: undefined,\n        dataState: \"empty\",\n        called: true,\n        loading: true,\n        networkStatus: NetworkStatus.loading,\n        previousData: undefined,\n        variables: {},\n      });\n    }\n\n    {\n      const [, result] = await takeSnapshot();\n\n      expect(result).toStrictEqualTyped({\n        data: { hello: \"world\" },\n        dataState: \"complete\",\n        called: true,\n        loading: false,\n        networkStatus: NetworkStatus.ready,\n        previousData: undefined,\n        variables: {},\n      });\n    }\n\n    await expect(takeSnapshot).not.toRerender();\n  });\n\n  it(\"should use variables passed to execute function when running the lazy execution function\", async () => {\n    const query = gql`\n      query ($id: number) {\n        hello(id: $id)\n      }\n    `;\n\n    const mocks = [\n      {\n        request: { query, variables: { id: 1 } },\n        result: { data: { hello: \"world 1\" } },\n        delay: 20,\n      },\n    ];\n\n    using _disabledAct = disableActEnvironment();\n    const { takeSnapshot, getCurrentSnapshot } =\n      await renderHookToSnapshotStream(() => useLazyQuery(query), {\n        wrapper: ({ children }) => (\n          <MockedProvider mocks={mocks}>{children}</MockedProvider>\n        ),\n      });\n\n    {\n      const [, result] = await takeSnapshot();\n\n      expect(result).toStrictEqualTyped({\n        data: undefined,\n        dataState: \"empty\",\n        called: false,\n        loading: false,\n        networkStatus: NetworkStatus.ready,\n        previousData: undefined,\n        variables: {},\n      });\n    }\n\n    const [execute] = getCurrentSnapshot();\n    const result = await execute({ variables: { id: 1 } });\n\n    expect(result).toStrictEqualTyped({\n      data: { hello: \"world 1\" },\n    });\n\n    {\n      const [, result] = await takeSnapshot();\n\n      expect(result).toStrictEqualTyped({\n        data: undefined,\n        dataState: \"empty\",\n        called: true,\n        loading: true,\n        networkStatus: NetworkStatus.setVariables,\n        previousData: undefined,\n        variables: { id: 1 },\n      });\n    }\n\n    {\n      const [, result] = await takeSnapshot();\n\n      expect(result).toStrictEqualTyped({\n        data: { hello: \"world 1\" },\n        dataState: \"complete\",\n        called: true,\n        loading: false,\n        networkStatus: NetworkStatus.ready,\n 