AAI,EAAE,CAAC,EAAE,UAAU,EAAE,KAAK,EAAE,EAAE,EAAE,CAAC,EAAE,CAAC;gCACpC,SAAS,EAAE,EAAE,UAAU,EAAE,IAAI,EAAE,aAAa,EAAE,KAAK,EAAE;6BACtD,CAAC;wBAJF,CAIE,EACJ,EAAE,OAAO,EAAE,IAAA,8BAAmB,EAAC,MAAM,CAAC,EAAE,CACzC,EAAA;;oBARO,YAAY,GAAK,CAAA,SAQxB,CAAA,aARmB;oBAUpB,qBAAM,MAAM,CAAC,YAAY,EAAE,CAAC,CAAC,QAAQ,CAAC,kBAAkB,CAAC;4BACvD,IAAI,EAAE,CAAC,EAAE,CAAC;4BACV,SAAS,EAAE,UAAU;4BACrB,QAAQ,EAAE,IAAI;yBACf,CAAC,EAAA;;oBAJF,SAIE,CAAC;oBAEH,qBAAM,MAAM,CAAC,YAAY,CAAC,CAAC,GAAG,CAAC,UAAU,EAAE,EAAA;;oBAA3C,SAA2C,CAAC;;;;;;;;;;;;;SAC7C,CAAC,CAAC;IAEH,IAAI,CAAC,+BAA+B,EAAE;;;;;;;;;oBAC9B,YAAY,2CAAG,IAAA,2CAAqB,GAAE,QAAA,CAAC;oBACpB,qBAAM,IAAA,gDAA0B,EACvD;4BACE,OAAA,IAAA,mBAAW,EAAC;gCACV,QAAQ,UAAA;gCACR,IAAI,EAAE;oCACJ,EAAE,UAAU,EAAE,KAAK,EAAE,EAAE,EAAE,CAAC,EAAE;oCAC5B,EAAE,UAAU,EAAE,KAAK,EAAE,EAAE,EAAE,CAAC,EAAE;iCAC7B;gCACD,SAAS,EAAE,EAAE,UAAU,EAAE,IAAI,EAAE,aAAa,EAAE,KAAK,EAAE;6BACtD,CAAC;wBAPF,CAOE,EACJ,EAAE,OAAO,EAAE,IAAA,8BAAmB,EAAC,MAAM,CAAC,EAAE,CACzC,EAAA;;oBAXO,YAAY,GAAK,CAAA,SAWxB,CAAA,aAXmB;oBAapB,qBAAM,MAAM,CAAC,YAAY,EAAE,CAAC,CAAC,QAAQ,CAAC,kBAAkB,CAAC;4BACvD,IAAI,EAAE,CAAC,EAAE,EAAE,IAAI,CAAC;4BAChB,SAAS,EAAE,SAAS;4BACpB,QAAQ,EAAE,KAAK;4BACf,OAAO,EAAE;gCACP,CAAC,EAAE,4CAA4C;6BAChD;yBACF,CAAC,EAAA;;oBAPF,SAOE,CAAC;oBAEH,qBAAM,MAAM,CAAC,YAAY,CAAC,CAAC,GAAG,CAAC,UAAU,EAAE,EAAA;;oBAA3C,SAA2C,CAAC;;;;;;;;;;;;;SAC7C,CAAC,CAAC;AACL,CAAC,CAAC,CAAC;AAEH,QAAQ,CAAC,IAAI,CAAC,YAAY,EAAE;IAC1B,IAAI,CAAC,wDAAwD,EAAE;QAC7D,IAAM,SAAS,GAAG,EAAyD,CAAC;QAC5E,IAAA,mBAAW,EAAC;YACV,QAAQ,EAAE,SAAS;YACnB,IAAI,EAAE,EAAE,UAAU,EAAE,OAAO,EAAE;YAC7B,SAAS,EAAE;gBACT,GAAG,EAAE,CAAC;gBACN,mBAAmB;gBACnB,mBAAmB,EAAE,QAAQ;aAC9B;SACF,CAAC,CAAC;IACL,CAAC,CAAC,CAAC;IAEH,IAAI,CAAC,oCAAoC,EAAE;QAEzC,IAAA,0BAAY,GAET,CAAC,OAAO,CAAC,aAAa,EAarB,CAAC;IACP,CAAC,CAAC,CAAC;AACL,CAAC,CAAC,CAAC","names":[],"sources":["/workspace/repo/src/react/hooks/__tests__/useFragment.test.tsx"],"sourcesContent":["import assert from \"assert\";\n\nimport {\n  act,\n  render,\n  renderHook,\n  screen,\n  waitFor,\n  within,\n} from \"@testing-library/react\";\nimport {\n  createRenderStream,\n  disableActEnvironment,\n  renderHookToSnapshotStream,\n  useTrackRenders,\n} from \"@testing-library/react-render-stream\";\nimport { userEvent } from \"@testing-library/user-event\";\nimport { expectTypeOf } from \"expect-type\";\nimport * as React from \"react\";\nimport type { Observer } from \"rxjs\";\nimport { Observable } from \"rxjs\";\n\nimport type {\n  DocumentNode,\n  OperationVariables,\n  Reference,\n  StoreObject,\n  TypedDocumentNode,\n} from \"@apollo/client\";\nimport {\n  ApolloClient,\n  ApolloLink,\n  DocumentTransform,\n  gql,\n  InMemoryCache,\n} from \"@apollo/client\";\nimport type { FragmentType } from \"@apollo/client/masking\";\nimport { ApolloProvider, useFragment, useQuery } from \"@apollo/client/react\";\nimport {\n  createClientWrapper,\n  spyOnConsole,\n} from \"@apollo/client/testing/internal\";\nimport { MockedProvider } from \"@apollo/client/testing/react\";\nimport { concatPagination } from \"@apollo/client/utilities\";\nimport { removeDirectivesFromDocument } from \"@apollo/client/utilities/internal\";\n\ndescribe(\"useFragment\", () => {\n  it(\"is importable and callable\", () => {\n    expect(typeof useFragment).toBe(\"function\");\n  });\n\n  type Item = {\n    __typename: string;\n    id: number;\n    text?: string;\n  };\n\n  const ListFragment: TypedDocumentNode<QueryDataWithExtra> = gql`\n    fragment ListFragment on Query {\n      list {\n        id\n      }\n      # Used to make sure ListFragment got used, even if the id field of the\n      # nested list items is provided by other means.\n      extra\n    }\n  `;\n\n  const ItemFragment: TypedDocumentNode<Item> = gql`\n    fragment ItemFragment on Item {\n      text\n    }\n  `;\n\n  interface QueryData {\n    __typename?: \"Query\";\n    list: Item[];\n  }\n\n  interface QueryDataWithExtra extends QueryData {\n    extra: string;\n  }\n\n  it(\"can rerender individual list elements\", async () => {\n    const cache = new InMemoryCache({\n      typePolicies: {\n        Item: {\n          fields: {\n            text(existing, { readField }) {\n              return existing || `Item #${readField(\"id\")}`;\n            },\n          },\n        },\n      },\n    });\n\n    const listQuery: TypedDocumentNode<QueryData> = gql`\n      query {\n        list {\n          id\n        }\n      }\n    `;\n\n    cache.writeQuery({\n      query: listQuery,\n      data: {\n        list: [\n          { __typename: \"Item\", id: 1 },\n          { __typename: \"Item\", id: 2 },\n          { __typename: \"Item\", id: 5 },\n        ],\n      },\n    });\n\n    const renders: string[] = [];\n\n    function List() {\n      renders.push(\"list\");\n      const { loading, data } = useQuery(listQuery);\n      expect(loading).toBe(false);\n      return (\n        <ol>{data?.list.map((item) => <Item key={item.id} id={item.id} />)}</ol>\n      );\n    }\n\n    function Item(props: { id: number }) {\n      renders.push(\"item \" + props.id);\n      const { complete, data } = useFragment({\n        fragment: ItemFragment,\n        fragmentName: \"ItemFragment\",\n        from: {\n          __typename: \"Item\",\n          id: props.id,\n        },\n      });\n      return <li>{complete ? data.text : \"incomplete\"}</li>;\n    }\n\n    render(\n      <MockedProvider cache={cache}>\n        <List />\n      </MockedProvider>\n    );\n\n    function getItemTexts() {\n      return screen.getAllByText(/^Item/).map(\n        // eslint-disable-next-line testing-library/no-node-access\n        (li) => li.firstChild!.textContent\n      );\n    }\n\n    await waitFor(() => {\n      expect(getItemTexts()).toStrictEqualTyped([\n        \"Item #1\",\n        \"Item #2\",\n        \"Item #5\",\n      ]);\n    });\n\n    expect(renders).toStrictEqualTyped([\"list\", \"item 1\", \"item 2\", \"item 5\"]);\n\n    await act(async () => {\n      cache.writeFragment({\n        fragment: ItemFragment,\n        data: {\n          __typename: \"Item\",\n          id: 2,\n          text: \"Item #2 updated\",\n        },\n      });\n    });\n\n    await waitFor(() => {\n      expect(getItemTexts()).toStrictEqualTyped([\n        \"Item #1\",\n        \"Item #2 updated\",\n        \"Item #5\",\n      ]);\n    });\n\n    expect(renders).toStrictEqualTyped([\n      \"list\",\n      \"item 1\",\n      \"item 2\",\n      \"item 5\",\n      // Only the second item should have re-rendered.\n      \"item 2\",\n    ]);\n\n    await act(async () => {\n      cache.modify({\n        fields: {\n          list(list: readonly Reference[], { readField }) {\n            return [\n              ...list,\n              cache.writeFragment({\n                fragment: ItemFragment,\n                data: {\n                  __typename: \"Item\",\n                  id: 3,\n                  text: \"Item #3 from cache.modify\",\n                },\n              })!,\n              cache.writeFragment({\n                fragment: ItemFragment,\n                data: {\n                  __typename: \"Item\",\n                  id: 4,\n                  text: \"Item #4 from cache.modify\",\n                },\n              })!,\n            ].sort(\n              (ref1, ref2) =>\n                readField<Item[\"id\"]>(\"id\", ref1)! -\n                readField<Item[\"id\"]>(\"id\", ref2)!\n            );\n          },\n        },\n      });\n    });\n\n    await waitFor(() => {\n      expect(getItemTexts()).toStrictEqualTyped([\n        \"Item #1\",\n        \"Item #2 updated\",\n        \"Item #3 from cache.modify\",\n        \"Item #4 from cache.modify\",\n        \"Item #5\",\n      ]);\n    });\n\n    expect(renders).toStrictEqualTyped([\n      \"list\",\n      \"item 1\",\n      \"item 2\",\n      \"item 5\",\n      \"item 2\",\n      // This is what's new:\n      \"list\",\n      \"item 1\",\n      \"item 2\",\n      \"item 3\",\n      \"item 4\",\n      \"item 5\",\n    ]);\n\n    await act(async () => {\n      cache.writeFragment({\n        fragment: ItemFragment,\n        data: {\n          __typename: \"Item\",\n          id: 4,\n          text: \"Item #4 updated\",\n        },\n      });\n    });\n\n    await waitFor(() => {\n      expect(getItemTexts()).toStrictEqualTyped([\n        \"Item #1\",\n        \"Item #2 updated\",\n        \"Item #3 from cache.modify\",\n        \"Item #4 updated\",\n        \"Item #5\",\n      ]);\n    });\n\n    expect(renders).toStrictEqualTyped([\n      \"list\",\n      \"item 1\",\n      \"item 2\",\n      \"item 5\",\n      \"item 2\",\n      \"list\",\n      \"item 1\",\n      \"item 2\",\n      \"item 3\",\n      \"item 4\",\n      \"item 5\",\n      // Only the fourth item should have re-rendered.\n      \"item 4\",\n    ]);\n\n    // set Item #2 back to its original value\n    await act(async () => {\n      cache.writeFragment({\n        fragment: ItemFragment,\n        data: {\n          __typename: \"Item\",\n          id: 2,\n          text: \"Item #2\",\n        },\n      });\n    });\n\n    await waitFor(() => {\n      expect(getItemTexts()).toStrictEqualTyped([\n        \"Item #1\",\n        \"Item #2\",\n        \"Item #3 from cache.modify\",\n        \"Item #4 updated\",\n        \"Item #5\",\n      ]);\n    });\n\n    expect(renders).toStrictEqualTyped([\n      \"list\",\n      \"item 1\",\n      \"item 2\",\n      \"item 5\",\n      \"item 2\",\n      \"list\",\n      \"item 1\",\n      \"item 2\",\n      \"item 3\",\n      \"item 4\",\n      \"item 5\",\n      \"item 4\",\n      // Only the second item should have re-rendered.\n      \"item 2\",\n    ]);\n\n    expect(cache.extract()).toStrictEqualTyped({\n      \"Item:1\": {\n        __typename: \"Item\",\n        id: 1,\n      },\n      \"Item:2\": {\n        __typename: \"Item\",\n        id: 2,\n        text: \"Item #2\",\n      },\n      \"Item:3\": {\n        __typename: \"Item\",\n        id: 3,\n        text: \"Item #3 from cache.modify\",\n      }