length property, which is\n        // good because \"length\" could be a name of an actual field that's\n        // missing, and it's somewhat unclear what the length of a sparse array\n        // should be, whereas object keys have a less ambiguous interpretation.\n        0: { text: \"Can't find field 'text' on Item:1 object\" },\n        1: { text: \"Can't find field 'text' on Item:2 object\" },\n        2: { text: \"Can't find field 'text' on Item:5 object\" },\n      },\n    });\n\n    checkHistory(2);\n\n    const data182WithText = {\n      __typename: \"Query\" as const,\n      list: [\n        { __typename: \"Item\", id: 1, text: \"oyez1\" },\n        { __typename: \"Item\", id: 8, text: \"oyez8\" },\n        { __typename: \"Item\", id: 2, text: \"oyez2\" },\n      ],\n    };\n\n    await act(async () => {\n      cache.writeQuery({\n        query: ListQueryWithText,\n        data: data182WithText,\n      });\n    });\n\n    await waitFor(() =>\n      expect(renderResult.current.data).toStrictEqualTyped(data182WithText)\n    );\n    expect(renderResult.current.complete).toBe(true);\n    expect(renderResult.current.missing).toBeUndefined();\n\n    checkHistory(3);\n\n    await act(async () =>\n      cache.batch({\n        update(cache) {\n          cache.evict({\n            id: cache.identify({\n              __typename: \"Item\",\n              id: 8,\n            }),\n          });\n\n          cache.evict({\n            id: cache.identify({\n              __typename: \"Item\",\n              id: 2,\n            }),\n            fieldName: \"text\",\n          });\n        },\n      })\n    );\n\n    await waitFor(() =>\n      expect(renderResult.current.data).toStrictEqualTyped({\n        __typename: \"Query\",\n        list: [\n          { __typename: \"Item\", id: 1, text: \"oyez1\" },\n          { __typename: \"Item\", id: 2 },\n        ],\n      })\n    );\n    expect(renderResult.current.complete).toBe(false);\n    expect(renderResult.current.missing).toStrictEqualTyped({\n      // TODO Figure out why Item:8 is not represented here. Likely because of\n      // auto-filtering of dangling references from arrays, but that should\n      // still be reflected here, if possible.\n      list: {\n        1: {\n          text: \"Can't find field 'text' on Item:2 object\",\n        },\n      },\n    });\n\n    checkHistory(4);\n\n    expect(cache.extract()).toStrictEqualTyped({\n      \"Item:1\": {\n        __typename: \"Item\",\n        id: 1,\n        text: \"oyez1\",\n      },\n      \"Item:2\": {\n        __typename: \"Item\",\n        id: 2,\n      },\n      \"Item:5\": {\n        __typename: \"Item\",\n        id: 5,\n      },\n      ROOT_QUERY: {\n        __typename: \"Query\",\n        list: [{ __ref: \"Item:1\" }, { __ref: \"Item:8\" }, { __ref: \"Item:2\" }],\n      },\n    });\n\n    expect(cache.gc().sort()).toStrictEqualTyped([\"Item:5\"]);\n  });\n\n  it(\"returns new diff when UseFragmentOptions change\", async () => {\n    const ListFragment: TypedDocumentNode<QueryData> = gql`\n      fragment ListFragment on Query {\n        list {\n          id\n        }\n      }\n    `;\n\n    const cache = new InMemoryCache({\n      typePolicies: {\n        Item: {\n          fields: {\n            text(existing, { readField }) {\n              return existing || `Item #${readField(\"id\")}`;\n            },\n          },\n        },\n      },\n    });\n\n    const client = new ApolloClient({\n      cache,\n      link: new ApolloLink(\n        (operation) =>\n          new Observable((observer) => {\n            if (operation.operationName === \"ListQueryWithItemFragment\") {\n              setTimeout(() => {\n                observer.next({\n                  data: {\n                    list: [\n                      { __typename: \"Item\", id: 1 },\n                      { __typename: \"Item\", id: 2 },\n                      { __typename: \"Item\", id: 5 },\n                    ],\n                  },\n                });\n                observer.complete();\n              }, 10);\n            } else {\n              observer.error(\n                `unexpected query ${operation.operationName || operation.query}`\n              );\n            }\n          })\n      ),\n    });\n\n    const listQuery: TypedDocumentNode<QueryData> = gql`\n      query ListQueryWithItemFragment {\n        list {\n          id\n          ...ItemFragment\n        }\n      }\n      ${ItemFragment}\n    `;\n\n    function List() {\n      const [currentItem, setCurrentItem] = React.useState(1);\n      useQuery(listQuery);\n\n      const { complete, data } = useFragment({\n        fragment: ListFragment,\n        from: { __typename: \"Query\" },\n      });\n\n      return complete ?\n          <>\n            <select\n              onChange={(e) => {\n                setCurrentItem(parseInt(e.currentTarget.value));\n              }}\n            >\n              {data.list.map((item) => (\n                <option key={item.id} value={item.id}>\n                  Select item {item.id}\n                </option>\n              ))}\n            </select>\n            <div>\n              <Item id={currentItem} />\n            </div>\n            <ol>\n              {data.list.map((item) => (\n                <Item key={item.id} id={item.id} />\n              ))}\n            </ol>\n          </>\n        : null;\n    }\n\n    function Item({ id }: { id: number }) {\n      const { complete, data } = useFragment({\n        fragment: ItemFragment,\n        from: {\n          __typename: \"Item\",\n          id,\n        },\n      });\n      return <li>{complete ? data.text : \"incomplete\"}</li>;\n    }\n\n    render(\n      <ApolloProvider client={client}>\n        <List />\n      </ApolloProvider>\n    );\n\n    function getItemTexts() {\n      return screen.getAllByText(/^Item/).map(\n        // eslint-disable-next-line testing-library/no-node-access\n        (li) => li.firstChild!.textContent\n      );\n    }\n\n    await waitFor(() => {\n      expect(getItemTexts()).toStrictEqualTyped([\n        // On initial render, Item #1 is selected\n        // and renders above the list\n        \"Item #1\",\n        \"Item #1\",\n        \"Item #2\",\n        \"Item #5\",\n      ]);\n    });\n\n    // Select \"Item #2\" via <select />\n    const user = userEvent.setup();\n    await user.selectOptions(\n      screen.getByRole(\"combobox\"),\n      screen.getByRole(\"option\", { name: \"Select item 2\" })\n    );\n\n    await waitFor(() => {\n      expect(getItemTexts()).toStrictEqualTyped([\n        // Now the selected item at the top should render\n        // \"Item #2\" + the list of items below\n        \"Item #2\",\n        \"Item #1\",\n        \"Item #2\",\n        \"Item #5\",\n      ]);\n    });\n  });\n\n  it(\"returns correct data when from changes\", async () => {\n    const client = new ApolloClient({\n      cache: new InMemoryCache(),\n      link: ApolloLink.empty(),\n    });\n    type User = { __typename: \"User\"; id: number; name: string };\n    const fragment: TypedDocumentNode<User> = gql`\n      fragment UserFragment on User {\n        id\n        name\n      }\n    `;\n\n    client.writeFragment({\n      fragment,\n      data: { __typename: \"User\", id: 1, name: \"Alice\" },\n    });\n\n    client.writeFragment({\n      fragment,\n      data: { __typename: \"User\", id: 2, name: \"Charlie\" },\n    });\n\n    using _disabledAct = disableActEnvironment();\n    const { takeSnapshot, rerender } = await renderHookToSnapshotStream(\n      ({ id }) => useFragment({ fragment, from: { __typename: \"User\", id } }),\n      {\n        initialProps: { id: 1 },\n        wrapper: ({ children }) => (\n          <ApolloProvider client={client}>{children}</ApolloProvider>\n        ),\n      }\n    );\n\n    {\n      const snapshot = await takeSnapshot();\n\n      expect(snapshot).toStrictEqualTyped({\n        complete: true,\n        data: { __typename: \"User\", id: 1, name: \"Alice\" },\n        dataState: \"complete\",\n      });\n    }\n\n    await rerender({ id: 2 });\n\n    {\n      const snapshot = await takeSnapshot();\n\n      expect(snapshot).toStrictEqualTyped({\n        complete: true,\n        data: { __typename: \"User\", id: 2, name: \"Charlie\" },\n        dataState: \"complete\",\n      });\n    }\n\n    await expect(takeSnapshot).not.toRerender();\n  });\n\n  it(\"returns correct data when options change\", async () => {\n    const client = new ApolloClient({\n      cache: new InMemoryCache(),\n      link: ApolloLink.empty(),\n    });\n    type User = { __typename: \"User\"; id: number; name: string };\n    const fragment: TypedDocumentNode<User> = gql`\n      fragment UserFragment on User {\n        id\n        name(casing: $casing)\n      }\n    `;\n\n    client.writeFragment({\n      fragment,\n      data: { __typename: \"User\", id: 1, name: \"ALICE\" },\n      variables: { casing: \"upper\" },\n    });\n\n    client.writeFragment({\n      fragment,\n      data: { __typename: \"User\", id: 1, name: \"alice\" },\n      variables: { casing: \"lower\" },\n    });\n\n    using _disabledAct = disableActEnvironment();\n    const { takeSnapshot, rerender } = await renderHookToSnapshotStream(\n      ({ casing }) =>\n        useFragment({\n          fragment,\n          from: { __typename: \"User\", id: 1 },\n          variables: { casing },\n        }),\n      {\n        initialProps: { casing: \"upper\" },\n        wrapper: ({ children }) => (\n          <ApolloProvider client={client}>{children}</ApolloProvider>\n        ),\n      }\n    );\n\n    {\n      const snapshot = await takeSnapshot();\n\n      expect(snapshot).toStrictEqualTyped({\n        complete: true,\n        data: { __typename: \"User\", id: 1, name: \"ALICE\" },\n        dataState: \"complete\",\n      });\n    }\n\n    await rerender({ casing: \"lower\" });\n\n    {\n      const snapshot = await takeSnapshot();\n\n      expect(snapshot).toStrictEqualTyped({\n        complete: true,\n        data: { __typename: \"User\", id: 1, name: \"alice\" },\n        dataState: \"complete\",\n      });\n    }\n\n    await expect(takeSnapshot).not.toRerender();\n  });\n\n  it(\"does not rerender when fields with @nonreactive change\", async () => {\n    type Post = {\n      __typename: \"Post\";\n      id: number;\n      title: string;\n      updatedAt: string;\n    };\n\n    const client = new ApolloClient({\n      cache: new InMemoryCache(),\n      link: ApolloLink.empty(),\n    });\n\n    const fragment: TypedDocumentNode<Post> = gql`\n      fragment PostFragment on Post {\n        id\n        title\n        updatedAt @nonreactive\n      }\n    `;\n\n    client.writeFragment({\n      fragment,\n      data: {\n        __typename: \"Post\",\n        id: 1,\n        title: \"Blog post\",\n        updatedAt: \"2024-01-01\",\n      },\n    });\n\n    using _disabledAct = disableActEnvironment();\n    const { takeSnapshot } = await renderHookToSnapshotStream(\n      () => useFragment({ fragment, from: { __typename: \"Post\", id: 1 } }),\n      {\n        wrapper: ({ children }) => (\n          <ApolloProvider client={client}>{children}</ApolloProvider>\n        ),\n      }\n    );\n\n    {\n      const snapshot = await takeSnapshot();\n\n      expect(snapshot).toStrictEqualTyped({\n        complete: true,\n        data: {\n          __typename: \"Post\",\n          id: 1,\n          title: \"Blog post\",\n          updatedAt: \"2024-01-01\",\n        },\n        dataState: \"complete\",\n      });\n    }\n\n    client.writeFragment({\n      fragment,\n      data: {\n        __typename: \"Post\",\n        id: 1,\n        title: \"Blog post\",\n        updatedAt: \"2024-02-01\",\n      },\n    });\n\n    await expect(takeSnapshot).not.toRerender();\n  });\n\n  it(\"does not rerender when fields with @nonreactive on nested fragment change\", async () => {\n    type Post = {\n      __typename: \"Post\";\n      id: number;\n      title: string;\n      updatedAt: string;\n    };\n\n    const client = new ApolloClient({\n      cache: new InMemoryCache(),\n      link: ApolloLink.empty(),\n    });\n\n    const fragment: TypedDocumentNode<Post> = gql`\n      fragment PostFragment on Post {\n        id\n        title\n        ...PostFields @nonreactive\n      }\n\n      fragment PostFields on Post {\n        updatedAt\n      }\n    `;\n\n    client.writeFragment({\n      fragment,\n      fragmentName: \"PostFragment\",\n      data: {\n        __typename: \"Post\",\n        id: 1,\n        title: \"Blog post\",\n        updatedAt: \"2024-01-01\",\n      },\n    });\n\n    using _disabledAct = disableActEnvironment();\n    const { takeSnapshot } = await renderHookToSnapshotStream(\n      () =>\n        useFragment({\n          fragment,\n          fragmentName: \"PostFragment\",\n          from: { __typename: \"Post\", id: 1 },\n        }),\n      {\n        wrapper: ({ children }) => (\n          <ApolloProvider client={client}>{children}</ApolloProvider>\n        ),\n      }\n    );\n\n    {\n      const snapshot = await takeSnapshot();\n\n      expect(snapshot).toStrictEqualTyped({\n        complete: true,\n        data: {\n          __typename: \"Post\",\n          id: 1,\n          title: \"Blog post\",\n          updatedAt: \"2024-01-01\",\n        },\n        dataState: \"complete\",\n      });\n    }\n\n    client.writeFragment({\n      fragment,\n      fragmentName: \"PostFragment\",\n      data: {\n        __typename: \"Post\",\n        id: 1,\n        title: \"Blog post\",\n        updatedAt: \"2024-02-01\",\n      },\n    });\n\n    await expect(takeSnapshot).not.toRerender();\n  });\n\n  it(\"warns when passing parent object to `from` when key fields are missing\", async () => {\n    using _ = spyOnConsole(\"warn\");\n\n    interface Fragment {\n      age: number;\n    }\n\n    const fragment: TypedDocumentNode<Fragment, never> = gql`\n      fragment UserFields on User {\n        age\n      }\n    `;\n\n    const client = new ApolloClient({\n      cache: new InMemoryCache(),\n      link: ApolloLink.empty(),\n    });\n\n    using _disabledAct = disableActEnvironment();\n    const { takeSnapshot } = await renderHookToSnapshotStream(\n      () => useFragment({ fragment, from: { __typename: \"User\" } }),\n      {\n        wrapper: ({ children }) => (\n          <ApolloProvider client={client}>{children}</ApolloProvider>\n        ),\n      }\n    );\n\n    {\n      const { data, complete } = await takeSnapshot();\n\n      expect(data).toStrictEqualTyped({});\n      // TODO: Update when https://github.com/apollographql/apollo-client/issues/12003 is fixed\n      expect(complete).toBe(true);\n    }\n\n    expect(console.warn).toHaveBeenCalledTimes(1);\n    expect(console.warn).toHaveBeenCalledWith(\n      \"Could not identify object passed to `from` for '%s' fragment, either because the object is non-normalized or the key fields are missing. If you are masking this object, please ensure the key fields are requested by the parent object.\",\n      \"UserFields\"\n    );\n  });\n\n  it(\"allows `null` as valid `from` value without warning\", async () => {\n    using _ = spyOnConsole(\"warn\");\n\n    interface Fragment {\n      age: number;\n    }\n\n    const fragment: TypedDocumentNode<Fragment, never> = gql`\n      fragment UserFields on User {\n        age\n      }\n    `;\n\n    const client = new ApolloClient({\n      cache: new InMemoryCache(),\n      link: ApolloLink.empty(),\n    });\n\n    using _disabledAct = disableActEnvironment();\n    const { takeSnapshot } = await renderHookToSnapshotStream(\n      () => useFragment({ fragment, from: null }),\n      {\n        wrapper: ({ children }) => (\n          <ApolloProvider client={client}>{children}</ApolloProvider>\n        ),\n      }\n    );\n\n    {\n      const { data, complete } = await takeSnapshot();\n\n      expect(data).toStrictEqualTyped({});\n      expect(complete).toBe(false);\n    }\n\n    expect(console.warn).not.toHaveBeenCalled();\n  });\n\n  it(\"properly handles changing from null to valid from value\", async () => {\n    using _ = spyOnConsole(\"warn\");\n\n    interface Fragment {\n      __typename: \"User\";\n      id: string;\n      age: number;\n    }\n\n    const fragment: TypedDocumentNode<Fragment, Record<string, never>> = gql`\n      fragment UserFields on User {\n        __typename\n        id\n        age\n      }\n    `;\n\n    const client = new ApolloClient({\n      cache: new InMemoryCache(),\n      link: ApolloLink.empty(),\n    });\n\n    client.writeFragment({\n      fragment,\n      data: {\n        __typename: \"User\",\n        id: \"1\",\n        age: 30,\n      },\n    });\n\n    using _disabledAct = disableActEnvironment();\n    const { takeSnapshot, rerender } = await renderHookToSnapshotStream(\n      ({ from }) => useFragment({ fragment, from }),\n      {\n        initialProps: { from: null as useFragment.Options<any, never>[\"from\"] },\n        wrapper: ({ children }) => (\n          <ApolloProvider client={client}>{children}</ApolloProvider>\n        ),\n      }\n    );\n\n    await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n      data: {},\n      dataState: \"partial\",\n      complete: false,\n    });\n\n    await rerender({ from: { __typename: \"User\", id: \"1\" } });\n\n    await expect(takeSnapshot()).resolves.toStrictEqualTyped({\n      data: { __typename: \"User\", id: \"1\", age: 30 },\n      dataState: \"complete\",\n      complete: true,\n    });\n  });\n\n  describe(\"tests with incomplete data\", () => {\n    let cache: InMemoryCache, wrapper: React.FunctionComponent;\n    const ItemFragment = gql`\n      fragment ItemFragment on Item {\n        id\n        text\n      }\n    `;\n\n    beforeEach(() => {\n      cache = new InMemoryCache();\n      wrapper = ({ children }: any) => (\n        <MockedProvider cache={cache}>{children}</MockedProvider>\n      );\n\n      // silence the console for the incomplete fragment write\n      {\n        using _spy = spyOnConsole(\"error\");\n        cache.writeFragment({\n          fragment: ItemFragment,\n          data: {\n            __typename: \"Item\",\n            id: 5,\n          },\n        });\n      }\n    });\n\n    it(\"assumes `returnPartialData: true` per default\", () => {\n      const { result } = renderHook(\n        () =>\n          useFragment({\n            fragment: ItemFragment,\n            from: { __typename: \"Item\", id: 5 },\n          }),\n        { wrapper }\n      );\n\n      expect(result.current.data).toStrictEqualTyped({\n        __typename: \"Item\",\n        id: 5,\n      });\n      expect(result.current.complete).toBe(false);\n    });\n  });\n\n  describe(\"return value `complete` property\", () => {\n    let cache: InMemoryCache, wrapper: React.FunctionComponent;\n    const ItemFragment: TypedDocumentNode<{\n      __typename: \"Item\";\n      id: number;\n      text: string;\n    }> = gql`\n      fragment ItemFragment on Item {\n        id\n        text\n      }\n    `;\n\n    beforeEach(() => {\n      cache = new InMemoryCache();\n      wrapper = ({ children }: any) => (\n        <MockedProvider cache={cache}>{children}</MockedProvider>\n      );\n    });\n\n    test(\"if all data is available, `complete` is `true`\", () => {\n      cache.writeFragment({\n        fragment: ItemFragment,\n        data: {\n          __typename: \"Item\",\n          id: 5,\n          text: \"Item #5\",\n        },\n      });\n\n      const { result } = renderHook(\n        () =>\n          useFragment({\n            fragment: ItemFragment,\n            from: { __typename: \"Item\", id: 5 },\n          }),\n        { wrapper }\n      );\n\n      expect(result.current).toStrictEqualTyped({\n        data: { __typename: \"Item\", id: 5, text: \"Item #5\" },\n        complete: true,\n        dataState: \"complete\",\n      });\n    });\n\n    test(\"if only partial data is available, `complete`