AC;4BAChB,KAAK,OAAA;4BACL,IAAI,EAAE,EAAE,KAAK,EAAE,QAAQ,EAAE;yBAC1B,CAAC,CAAC;oBACL,CAAC;oBAgBkB,qBAAM,IAAA,qBAAe,EAAC;4BACvC,IAAI,EAAE,oBAAC,SAAS,OAAG;4BACnB,OAAO,EAAE,EAAE,MAAM,QAAA,EAAE;4BACnB,cAAc,EAAE,0BAAS;yBAC1B,CAAC,EAAA;;oBAJM,MAAM,GAAK,CAAA,SAIjB,CAAA,OAJY;oBAMd,MAAM,CAAC,MAAM,CAAC,UAAU,CAAC,QAAQ,EAAE,GAAG,CAAC,CAAC,CAAC,SAAS,CAChD,UAAG,IAAI,CAAC,SAAS,CAAC,cAAc,CAAC,CAAE,CACpC,CAAC;oBACF,MAAM,CAAC,OAAO,CAAC,CAAC,qBAAqB,CAAC,CAAC,CAAC,CAAC;;;;SAC1C,CACF,CAAC;AACJ,CAAC,CAAC,CAAC","names":[],"sources":["/workspace/repo/src/react/ssr/__tests__/prerenderStatic.test.tsx"],"sourcesContent":["/* eslint-disable testing-library/render-result-naming-convention */\n// not exported\n// eslint-disable-next-line local-rules/no-relative-imports\nimport \"../../../testing/internal/messageChannelPolyfill.js\";\n\nimport \"./polyfillReactDomTypes.d.ts\";\n\nimport { expectTypeOf } from \"expect-type\";\nimport { JSDOM } from \"jsdom\";\nimport jsesc from \"jsesc\";\nimport * as React from \"react\";\nimport { renderToStaticMarkup, renderToString } from \"react-dom/server\";\nimport {\n  type PrerenderResult,\n  type PrerenderToNodeStreamResult,\n} from \"react-dom/static\";\nimport { prerender, resumeAndPrerender } from \"react-dom/static.browser\";\nimport {\n  prerenderToNodeStream,\n  resumeAndPrerenderToNodeStream,\n} from \"react-dom/static.node\";\n\nimport type { TypedDocumentNode } from \"@apollo/client\";\nimport {\n  ApolloClient,\n  ApolloLink,\n  gql,\n  InMemoryCache,\n  NetworkStatus,\n} from \"@apollo/client\";\nimport {\n  ApolloProvider,\n  getApolloContext,\n  type SkipToken,\n  skipToken,\n  useQuery,\n  useSuspenseQuery,\n} from \"@apollo/client/react\";\nimport { prerenderStatic } from \"@apollo/client/react/ssr\";\nimport { MockLink, MockSubscriptionLink } from \"@apollo/client/testing\";\nimport { resetApolloContext, wait } from \"@apollo/client/testing/internal\";\nimport { InvariantError } from \"@apollo/client/utilities/invariant\";\n\nbeforeEach(() => {\n  // We are running tests with multiple different renderers, and that can result in a warning like\n  // > Detected multiple renderers concurrently rendering the same context provider. This is currently unsupported.\n  // This avoids that.\n  resetApolloContext();\n});\n// @ts-ignore\nglobal.setImmediate ||= (fn) => setTimeout(fn, 0);\n\nfunction testSetup() {\n  const query1: TypedDocumentNode<{ hello: string }> = gql`\n    query {\n      hello\n    }\n  `;\n  const query2: TypedDocumentNode<{ whoami: { name: string } }> = gql`\n    query {\n      whoami {\n        name\n      }\n    }\n  `;\n  const query3: TypedDocumentNode<{ currentTime: string }> = gql`\n    query {\n      currentTime\n    }\n  `;\n\n  function Outlet() {\n    const { data } = useSuspenseQuery(query1);\n\n    return (\n      <div>\n        <p>Hello {data.hello}!</p>\n        <React.Suspense>\n          <Parent />\n        </React.Suspense>\n      </div>\n    );\n  }\n\n  function Parent() {\n    const { data } = useSuspenseQuery(query2);\n\n    return (\n      <>\n        <p>My name is {data.whoami.name}!</p>\n        <React.Suspense>\n          <Child />\n        </React.Suspense>\n      </>\n    );\n  }\n  function Child() {\n    const { data } = useSuspenseQuery(query3);\n\n    return (\n      <>\n        <p>Current time is {data.currentTime}!</p>\n      </>\n    );\n  }\n\n  const mocks = [\n    {\n      request: { query: query1 },\n      result: { data: { hello: \"world\" } },\n      maxUsageCount: 1,\n    },\n    {\n      request: { query: query2 },\n      result: { data: { whoami: { name: \"Apollo\" } } },\n      maxUsageCount: 1,\n    },\n    {\n      request: { query: query3 },\n      result: { data: { currentTime: \"2025-03-26T14:40:53.118Z\" } },\n      maxUsageCount: 1,\n    },\n  ];\n  const mockLink = new MockLink(mocks);\n  return {\n    Outlet,\n    mocks,\n    mockLink,\n    query1,\n    query2,\n    query3,\n  };\n}\n\ntest.each([\n  [\"prerender\", prerender satisfies prerenderStatic.PrerenderToWebStream],\n  [\n    \"prerenderToNodeStream\",\n    prerenderToNodeStream satisfies prerenderStatic.PrerenderToNodeStream,\n  ],\n] as const)(\n  \"real-life kitchen sink use case with %s and `useSuspenseQuery`\",\n  async (_, prerender) => {\n    // reset things that might have been set by a previous run of this test with\n    // a different runner\n    (window as any).__APOLLO_CLIENT_INIT__ = undefined;\n    window.document.documentElement.innerHTML = \"<head></head><body></body>\";\n\n    const throwingLink = new ApolloLink(() => {\n      throw new Error(\n        \"This ApolloClient instance should not need to make requests!\"\n      );\n    });\n\n    const { Outlet, mockLink: ssrLink } = testSetup();\n    // from here on it's essentially what a userland app could look like\n\n    function makeClient(link = throwingLink) {\n      return new ApolloClient({\n        cache: new InMemoryCache(),\n        link,\n      });\n    }\n    function App() {\n      const externalClient = React.useContext(getApolloContext()).client;\n      const [client] = React.useState<ApolloClient>(\n        externalClient || makeClient\n      );\n      if ((window as any).__APOLLO_CLIENT_INIT__) {\n        client.restore((window as any).__APOLLO_CLIENT_INIT__);\n      }\n\n      return (\n        <html>\n          <head>\n            <meta charSet=\"utf-8\" />\n            <meta\n              name=\"viewport\"\n              content=\"width=device-width, initial-scale=1\"\n            />\n            <link rel=\"stylesheet\" href=\"/styles.css\"></link>\n            <title>My app</title>\n          </head>\n          <body>\n            <ApolloProvider client={client}>\n              <React.Suspense fallback=\"Loading...\">\n                <Outlet />\n              </React.Suspense>\n            </ApolloProvider>\n          </body>\n        </html>\n      );\n    }\n\n    async function ssr() {\n      const client = makeClient(ssrLink);\n      const signal 